# --- ④ 독립적인지 ---

class CafeKioskTest {
    CafeKiosk cafeKiosk = new CafeKiosk();

    @Test
    void add() {
        cafeKiosk.add(new Americano());
        assertThat(cafeKiosk.getBeverages()).hasSize(1);
    }

    @Test
    void empty() {
        assertThat(cafeKiosk.getBeverages()).isEmpty();
    }
}

$ ./gradlew test

CafeKioskTest > add() PASSED
CafeKioskTest > empty() PASSED

